/**
 * apiv3 (Laravel 13) için merkezi, auth-farkında istek yardımcısı.
 *
 * Legacy api'de her serviste tekrarlanan inline fetch'in (base URL + header + token +
 * hata yönetimi) tek yerde toplanmış modern karşılığı. tsbnext → apiv3 taşımasında
 * migrate edilen her servis kademe kademe buna bağlanır.
 *
 * Auth modları:
 *  - "app-token" (varsayılan): sunucu sırrı X-App-Token. Sunucuda doğrudan apiv3'e
 *    eklenir; tarayıcıda token sızdırılamayacağı için /api/apiv3 proxy'sine gidilir
 *    (proxy sunucu tarafında token'ı enjekte eder).
 *  - "sanctum": login'li B2C kullanıcı. `token` ile Bearer gönderilir (cookie
 *    `auth-token-v3`). Tarayıcıda yine proxy üzerinden gider, Authorization korunur.
 *  - "none": gate'siz public uç.
 *
 * GET dışı isteklerde gövde JSON olarak gönderilir. Yanıt JSON parse edilip döner;
 * `res.ok` değilse `ApiError` fırlatılır (Laravel 422 doğrulama hatalarında
 * `error.errors` alanı alan→mesaj dizilerini taşır).
 */

import { forceLogout, hasAuthCookie, haltForLogout } from "./authSession";

const isServer = (): boolean => typeof window === "undefined";

type AuthMode = "app-token" | "sanctum" | "none";

export type ApiClientOptions = {
    method?: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
    /** GET dışı istekler için gövde: JSON'a çevrilir; FormData ise olduğu gibi gönderilir (multipart). */
    body?: unknown;
    /** Auth modu (varsayılan: "app-token"). */
    auth?: AuthMode;
    /** "sanctum" modu için Bearer token (genelde cookie `auth-token-v3`). */
    token?: string;
    /** Next.js fetch cache modu. */
    cache?: RequestCache;
    /** Next.js ISR revalidate süresi (saniye). */
    revalidate?: number;
    /** Ek/override header'lar. */
    headers?: Record<string, string>;
};

export class ApiError extends Error {
    status: number;
    body: any;
    /** Laravel 422 doğrulama hataları: { field: string[] }. */
    errors?: Record<string, string[]>;

    constructor(status: number, body: any) {
        super(body?.message || `Request failed with status ${status}`);
        this.name = "ApiError";
        this.status = status;
        this.body = body;
        this.errors = body?.errors;
    }
}

function buildUrl(path: string): string {
    const clean = path.startsWith("/") ? path : `/${path}`;
    // Sunucuda doğrudan apiv3; tarayıcıda token enjekte eden proxy.
    return isServer() ? `${process.env.NEXT_PUBLIC_APIV3_URL ?? ""}${clean}` : `/api/apiv3${clean}`;
}

export async function apiClient<T = any>(path: string, opts: ApiClientOptions = {}): Promise<T> {
    const { method = "GET", body, auth = "app-token", token } = opts;

    const isForm = typeof FormData !== "undefined" && body instanceof FormData;

    const headers: Record<string, string> = {
        Accept: "application/json",
        "Content-Language": "en",
        ...opts.headers,
    };

    // FormData'da Content-Type'ı tarayıcı (boundary ile) kendi koyar; elle koyma.
    if (!isForm) {
        headers["Content-Type"] = "application/json";
    }

    // app-token: yalnızca sunucuda eklenir (tarayıcıda proxy ekler).
    if (auth === "app-token" && isServer()) {
        headers["X-App-Token"] = process.env.APIV3_APP_TOKEN ?? "";
    }
    if (auth === "sanctum" && token) {
        headers["Authorization"] = `Bearer ${token}`;
    }

    const init: RequestInit = { method, headers };
    if (body !== undefined && method !== "GET") {
        init.body = isForm ? (body as FormData) : JSON.stringify(body);
    }
    if (opts.cache) init.cache = opts.cache;
    if (opts.revalidate !== undefined) init.next = { revalidate: opts.revalidate };

    const res = await fetch(buildUrl(path), init);

    const text = await res.text();
    const data = text ? safeJson(text) : null;

    // Geçersiz/süresi dolmuş token veya disable edilmiş hesap → apiv3 401 döner.
    // Tarayıcıda ve kullanıcı kendini login'li sanıyorsa (cookie var) oturumu zorla
    // kapat: tüm auth cookie'leri silinip sayfa sessizce reload edilir. Anonim
    // kullanıcının public/app-token 401'inde tetiklenmez (cookie yok) → döngü olmaz.
    if (res.status === 401 && !isServer() && hasAuthCookie()) {
        forceLogout();
        // Sessizce askıya al: ApiError fırlatma → Sentry'e gürültü düşmesin, overlay
        // çakmasın. Tek temiz sonuç reload. (Genelde global fetch interceptor zaten
        // bu noktadan önce askıya alır; bu, interceptor kurulu değilse yedektir.)
        return haltForLogout<T>();
    }

    if (!res.ok) {
        throw new ApiError(res.status, data);
    }

    return data as T;
}

function safeJson(text: string): any {
    try {
        return JSON.parse(text);
    } catch {
        return text;
    }
}
